## C++

```cpp
class DisjointSet {
public:
    vector<int> parent, size;

    DisjointSet(int n) {
        parent.resize(n);
        size.resize(n, 1);

        for (int i = 0; i < n; i++)
            parent[i] = i;
    }

    int findUPar(int node) {
        if (parent[node] == node)
            return node;
        return parent[node] = findUPar(parent[node]);
    }

    void unionBySize(int u, int v) {
        int pu = findUPar(u);
        int pv = findUPar(v);

        if (pu == pv) return;

        if (size[pu] < size[pv]) {
            parent[pu] = pv;
            size[pv] += size[pu];
        } else {
            parent[pv] = pu;
            size[pu] += size[pv];
        }
    }
};

class Solution {
public:
    vector<vector<string>> accountsMerge(vector<vector<string>>& accounts) {
        int n = accounts.size();
        DisjointSet ds(n);

        unordered_map<string, int> emailToAccount;

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < accounts[i].size(); j++) {
                string email = accounts[i][j];

                if (!emailToAccount.count(email))
                    emailToAccount[email] = i;
                else
                    ds.unionBySize(i, emailToAccount[email]);
            }
        }

        vector<vector<string>> mergedEmails(n);

        for (auto &it : emailToAccount) {
            string email = it.first;
            int parent = ds.findUPar(it.second);
            mergedEmails[parent].push_back(email);
        }

        vector<vector<string>> ans;

        for (int i = 0; i < n; i++) {
            if (mergedEmails[i].empty())
                continue;

            sort(mergedEmails[i].begin(), mergedEmails[i].end());

            vector<string> temp;
            temp.push_back(accounts[i][0]);

            for (auto &email : mergedEmails[i])
                temp.push_back(email);

            ans.push_back(temp);
        }

        return ans;
    }
};
```

