class DisjointSet:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, node):
        if self.parent[node] != node:
            self.parent[node] = self.find(self.parent[node])
        return self.parent[node]

    def union(self, u, v):
        pu = self.find(u)
        pv = self.find(v)

        if pu == pv:
            return

        if self.size[pu] < self.size[pv]:
            self.parent[pu] = pv
            self.size[pv] += self.size[pu]
        else:
            self.parent[pv] = pu
            self.size[pu] += self.size[pv]


class Solution:
    def accountsMerge(self, accounts):
        n = len(accounts)
        ds = DisjointSet(n)

        email_to_account = {}

        # Merge accounts having common emails
        for i in range(n):
            for email in accounts[i][1:]:
                if email not in email_to_account:
                    email_to_account[email] = i
                else:
                    ds.union(i, email_to_account[email])

        # Group emails by parent
        merged_emails = [[] for _ in range(n)]

        for email, account in email_to_account.items():
            parent = ds.find(account)
            merged_emails[parent].append(email)

        # Build answer
        ans = []

        for i in range(n):
            if not merged_emails[i]:
                continue

            merged_emails[i].sort()
            ans.append([accounts[i][0]] + merged_emails[i])

        return ans
