class Solution {

    static List<List<String>> accountsMerge(List<List<String>> accounts) {
        DisjointSet ds = new DisjointSet(accounts.size());
        HashMap<String, Integer> map = new HashMap<>();
        for(int i=0; i<accounts.size(); i++){
            for(int j=1; j<accounts.get(i).size(); j++){
                String mail = accounts.get(i).get(j);
                if(map.containsKey(mail)){
                    ds.union(map.get(mail), i);
                }else{
                    map.put(mail, i);
                }
            }
        }
        ArrayList<String>[] mergedAccounts = new ArrayList[accounts.size()];
        for(int i=0; i<mergedAccounts.length; i++){
            mergedAccounts[i] = new ArrayList<>();
            mergedAccounts[i].add(accounts.get(i).get(0));
        }
        for(String key: map.keySet()){
            int up = ds.findUParent(map.get(key));
            mergedAccounts[up].add(key);
        }
        List<List<String>> res = new ArrayList<>();
        for (ArrayList<String> mergedAccount : mergedAccounts) {
            if (mergedAccount.size() > 1) {
                Collections.sort(mergedAccount.subList(1, mergedAccount.size()));
                res.add(mergedAccount);
            }
        }
        return res;
    }
}
class DisjointSet{
    int[] size;
    int[] parent;
    DisjointSet(int n){
        this.size = new int[n];
        this.parent = new int[n];
        for(int i=0; i<n; i++) parent[i]=i;
    }

    int findUParent(int node){
        if(node == parent[node]) return node;
        int up = findUParent(parent[node]);
        parent[node]=up;
        return up;
    }

    void union(int node1, int node2){
        int node1Up = findUParent(node1);
        int node2Up = findUParent(node2);
        if(node1Up == node2Up) return;
        if(size[node1Up] < size[node2Up]){
            parent[node1Up] = node2Up;
            size[node1Up] = size[node1Up] + size[node2Up];
        }else{
            parent[node2Up] = node1Up;
            size[node2Up] = size[node1Up] + size[node2Up];
        }
    }
}

